import React from "react";
import classNames from "classnames";
import { _t } from "../../../languageHandler";

type Props = React.AnchorHTMLAttributes<HTMLAnchorElement>;

export default function ExternalLink({
    className, children, target = "_blank", rel = "noreferrer noopener", ...props
}: Props): JSX.Element {
    return <a {...props} className={classNames("mx_ExternalLink", className)} target={target} rel={rel}>
        { children }
        <span className="mx_ExternalLink_icon" aria-hidden="true" />
        { target === "_blank" && <span className="mx_ExternalLink_screenReader">
            { " " }{ _t("Opens in a new tab") }
        </span> }
    </a>;
}

